package ai.eva.android.probe;
import android.app.*;import android.os.*;import android.widget.*;import android.view.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import org.json.*;

/** Local text editor with private recoverable draft and conflict-preserving save. */
public class WorkspaceEditActivity extends ToolPageActivity {
 WorkspaceEditor store;String relative,revision,baseline="";EditText editor;TextView status;File draft;boolean ready;
 final Handler handler=new Handler(Looper.getMainLooper());final Runnable persistDraft=()->saveDraft();
 public void onCreate(Bundle state){super.onCreate(state);page("编辑文件","");try{
  store=new WorkspaceEditor(WorkspaceFiles.root(this));relative=getIntent().getStringExtra("path");store.path(relative);
  File dir=new File(getFilesDir(),"editor-drafts");dir.mkdirs();draft=new File(dir,WorkspaceEditor.hash(relative.getBytes(StandardCharsets.UTF_8))+".json");String initial=null;boolean restored=false;JSONObject recovered=null;
  if(draft.isFile()){try{if(draft.length()>2*1024*1024)throw new IOException("草稿过大");recovered=new JSONObject(new String(Files.readAllBytes(draft.toPath()),StandardCharsets.UTF_8));if(!relative.equals(recovered.optString("path")))throw new IOException("草稿路径不匹配");initial=recovered.getString("text");revision=recovered.getString("revision");restored=true;}catch(Exception e){throw new IOException("草稿无法读取，未覆盖原文件。请先恢复草稿。",e);}}
  try{WorkspaceEditor.Document doc=store.read(relative);baseline=doc.text;if(!restored){revision=doc.revision;initial=doc.text;}}catch(IOException e){if(!restored)throw e;baseline=null;}
  pageTitle.setText(new File(relative).getName());header.addView(actionIcon("file","保存文件",()->save()));
  status=label(restored?"已恢复未保存草稿；保存时检查文件版本":"UTF-8 · 256 KB 上限",12);body.addView(status);
  LinearLayout actions=new LinearLayout(this);actions.addView(button("保存",()->save()));actions.addView(button("另存为",()->saveAs()));actions.addView(button("重新读取",()->reload()));body.addView(actions);
  editor=new EditText(this);editor.setTextSize(14);editor.setTextColor(ink);editor.setGravity(Gravity.TOP|Gravity.LEFT);editor.setTypeface(android.graphics.Typeface.MONOSPACE);editor.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);editor.setImeOptions(android.view.inputmethod.EditorInfo.IME_FLAG_NO_EXTRACT_UI);editor.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(WorkspaceEditor.MAX_BYTES)});editor.setText(initial);editor.setContentDescription("文件文本编辑器");body.addView(editor,new LinearLayout.LayoutParams(-1,0,1));ready=true;
  editor.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){status.setText("未保存 · 草稿自动保留");handler.removeCallbacks(persistDraft);handler.postDelayed(persistDraft,400);}public void afterTextChanged(android.text.Editable e){}});
 }catch(Exception e){body.addView(label("无法编辑："+e.getMessage(),14));}}
 boolean dirty(){return ready&&!editor.getText().toString().equals(baseline);}
 void saveDraft(){if(!ready)return;try{if(!dirty()){Files.deleteIfExists(draft.toPath());return;}byte[] bytes=new JSONObject().put("path",relative).put("revision",revision).put("text",editor.getText().toString()).toString().getBytes(StandardCharsets.UTF_8);File tmp=new File(draft.getPath()+".tmp");Files.write(tmp.toPath(),bytes);Files.move(tmp.toPath(),draft.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(Exception e){status.setText("草稿保存失败："+e.getMessage());}}
 void save(){if(!ready)return;try{WorkspaceEditor.Document d=store.save(relative,editor.getText().toString(),revision);revision=d.revision;baseline=d.text;saveDraft();status.setText("已保存到工作区");}catch(Exception e){saveDraft();status.setText(e.getMessage());}}
 void saveAs(){EditText name=new EditText(this);name.setSingleLine();name.setHint("新文件名");AlertDialog dialog=new AlertDialog.Builder(this).setTitle("将草稿另存为").setView(name).setNegativeButton("取消",null).setPositiveButton("保存",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{String n=name.getText().toString().trim();if(n.contains("/")||n.contains("\\"))throw new IOException("请输入文件名，不包含目录");int slash=relative.lastIndexOf('/');String target=(slash<0?"":relative.substring(0,slash+1))+n;if(!java.nio.file.Files.isDirectory(store.path(relative).getParent()))target=n;store.create(target,editor.getText().toString(),false);status.setText("草稿已另存为 "+target);dialog.dismiss();}catch(Exception e){name.setError(e.getMessage());}}));dialog.show();}
 void reload(){new AlertDialog.Builder(this).setTitle("重新读取文件？").setMessage("将丢弃这个文件的未保存草稿，读取工作区最新内容。").setNegativeButton("取消",null).setPositiveButton("重新读取",(d,w)->{try{WorkspaceEditor.Document value=store.read(relative);baseline=value.text;revision=value.revision;editor.setText(value.text);saveDraft();status.setText("已读取最新文件");}catch(Exception e){status.setText(e.getMessage());}}).show();}
 protected void onPause(){handler.removeCallbacks(persistDraft);saveDraft();super.onPause();}
 void leavePage(){onBackPressed();}
 public void onBackPressed(){if(!dirty()){finish();return;}saveDraft();new AlertDialog.Builder(this).setTitle("有未保存的修改").setMessage("可以保留草稿离开，下次打开文件时继续编辑。").setNegativeButton("继续编辑",null).setNeutralButton("保留草稿离开",(d,w)->finish()).setPositiveButton("保存",(d,w)->save()).show();}
}
